from articles import ARTICLES
from new_guides import GUIDE_DETAILS
from pathlib import Path
from html import escape
import json, re, shutil

ROOT=Path(__file__).parent; OUT=ROOT/'dist'; IMG=ROOT/'public'/'images'
if OUT.exists(): shutil.rmtree(OUT)
OUT.mkdir(); (OUT/'images').mkdir()
for image in IMG.glob('*'): shutil.copy2(image,OUT/'images'/image.name)
shutil.copy2(ROOT/'public'/'style.css',OUT/'style.css')
credits=json.loads((ROOT/'image_credits.json').read_text()) if (ROOT/'image_credits.json').exists() else []
categories=['Dehumidifiers','Vacuums','Portable Power','Home Tech','Smart Home & AI']
stores={'Aeocky':'https://www.amazon.com/stores/AeockyDirect/page/3DC48C36-6A6A-495B-8F73-C17D85588886','Jackery':'https://www.amazon.com/stores/JackeryInc/page/17542FA1-CF54-41D6-8439-3885804D5DB8','wavytalk':'https://www.amazon.com/stores/wavytalk-HairTalks/page/823F971D-4C47-4483-A5AC-2E139FA6583A','roborock':'https://www.amazon.com/stores/roborock/page/69ADA24D-41D1-454D-9AAC-68D2B6252352'}
stores.update({brand: detail['source'] for brand, detail in GUIDE_DETAILS.items()})
def slug(s): return re.sub(r'[^a-z0-9]+','-',s.lower()).strip('-')
def e(s):return escape(s,quote=True)
PHOTO_ORDER=list(range(len(ARTICLES)))
def photo_query(i):
    j=PHOTO_ORDER[i]
    return credits[j]['query'] if j<len(credits) else ARTICLES[i][0]
def image(i):
    j=PHOTO_ORDER[i]
    p=credits[j].get('file','') if j<len(credits) else ''
    return p or '/images/editorial-fallback.svg'
def url(a): return '/stories/'+slug(a[1])+'/'
def caturl(c):return '/category/'+slug(c)+'/'
def card(a,i,featured=False):
    return f'<article class="card {"featured" if featured else ""}"><a href="{url(a)}" class="card-image"><img src="{image(i)}" alt="{e(photo_query(i))}" loading="lazy"></a><div class="eyebrow"><span class="dot"></span><a href="{caturl(a[0])}">{e(a[0])}</a></div><h3><a href="{url(a)}">{e(a[1])}</a></h3><p>{e(a[2])}</p><div class="byline">By Catonlee Editors</div></article>'
def shell(title,desc,body,path='/',extra=''):
    canonical='https://catonlee.com'+path
    nav=''.join(f'<a href="{caturl(c)}">{e(c)}</a>' for c in categories)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | Catonlee</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{canonical}"><meta property="og:title" content="{e(title)} | Catonlee"><meta property="og:description" content="{e(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://catonlee.com/images/og.svg"><link rel="icon" href="/images/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css">{extra}</head><body><a class="skip" href="#main">Skip to content</a><div class="top-strip">Useful ideas for a more comfortable, capable home <span>✦</span></div><header class="site-header"><a class="logo" href="/" aria-label="Catonlee home">catonlee<span class="logo-mark">.</span></a><nav id="nav" aria-label="Main navigation">{nav}<a href="/about/">About</a></nav><button class="menu-button" aria-label="Open menu" aria-expanded="false" onclick="const n=document.getElementById('nav');n.classList.toggle('open');this.setAttribute('aria-expanded',n.classList.contains('open'))">☰</button></header><main id="main">{body}</main><footer><div class="footer-main"><div><a class="logo" href="/">catonlee<span class="logo-mark">.</span></a><p>Good things for the spaces we live in.</p></div><div><h3>Explore</h3>{nav}</div><div><h3>About Catonlee</h3><a href="/about/">About</a><a href="/contact/">Contact</a><a href="/affiliate-disclosure/">Affiliate Disclosure</a></div><div><h3>Site information</h3><a href="/privacy-policy/">Privacy Policy</a><a href="/terms/">Terms of Use</a><a href="/cookie-notice/">Cookie Notice</a><a href="/image-credits/">Image Credits</a></div></div><div class="footer-bottom">© 2026 Catonlee. Independent home and technology buying advice. Some links may support this site.</div></footer><script>document.addEventListener('click',e=>{{if(!e.target.closest('.site-header')){{document.getElementById('nav').classList.remove('open');document.querySelector('.menu-button').setAttribute('aria-expanded','false')}}}})</script></body></html>'''
def write(path,content):
    p=OUT/path.strip('/')/'index.html' if path!='/' else OUT/'index.html'
    p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)

hero=ARTICLES[-1]
body=f'''<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span>{hero[0]}</div><h1>Home feels better when the details work.</h1><p>Practical ideas for the appliances, tools, and small decisions that make everyday living easier.</p><a class="text-link" href="{url(hero)}">Explore the latest story <span>↗</span></a></div><a class="hero-image" href="{url(hero)}"><img src="{image(len(ARTICLES)-1)}" alt="A comfortable living space ready for everyday life"></a></section><div class="container"><div class="section-head"><h2>Latest Stories</h2><a href="/all-stories/">See all stories ↗</a></div><div class="grid grid-3">{''.join(card(a,i) for i,a in list(enumerate(ARTICLES))[-3:][::-1])}</div></div>'''
for c in categories:
    entries=[(i,a) for i,a in enumerate(ARTICLES) if a[0]==c]
    body+=f'<section class="container category-block"><div class="section-head"><h2>{e(c)}</h2><a href="{caturl(c)}">See More ↗</a></div><div class="grid grid-4">'+''.join(card(a,i) for i,a in entries[:4])+'</div></section>'
body+='<section class="closing"><span class="dot"></span><h2>Make room for what matters.</h2><p>Explore buying advice shaped around actual rooms, routines, and tradeoffs.</p><a class="button" href="/all-stories/">Read all stories</a></section>'
write('/',shell('Home & everyday tech ideas','Practical buying advice for home appliances, cleaning, portable power, and everyday technology.',body))

for c in categories:
    entries=[(i,a) for i,a in enumerate(ARTICLES) if a[0]==c]
    b=f'<section class="archive container"><h1>{e(c)}</h1><div class="section-head"><h2>Latest in {e(c)}</h2><span>{len(entries)} stories</span></div><div class="grid grid-4">'+''.join(card(a,i) for i,a in entries)+'</div></section>'
    write(caturl(c),shell(c,f'Practical {c.lower()} buying guides for real homes and routines.',b,caturl(c)))

write('/all-stories/',shell('All Stories',f'Explore {len(ARTICLES)} independent home and technology buying guides.',f'<section class="archive container"><h1>All Stories</h1><div class="section-head"><h2>Explore the latest</h2><span>{len(ARTICLES)} stories</span></div><div class="grid grid-4">'+''.join(card(a,i) for i,a in reversed(list(enumerate(ARTICLES))))+'</div></section>','/all-stories/'))

for i,a in enumerate(ARTICLES):
    c,title,scene,advice,tradeoff,brand=a; merchant=stores[brand]
    related=[(j,x) for j,x in reversed(list(enumerate(ARTICLES))) if x[0]==c and j!=i][:3]
    detail=GUIDE_DETAILS.get(brand)
    detail_html=(f'<h2>What {e(brand)} offers today</h2><p>{e(detail["fact"])}</p><p>{e(detail["context"])}</p><p class="source-note">Based on <a href="{e(detail["source"])}" target="_blank" rel="noopener">published brand information</a>, checked November 7, 2026.</p>') if detail else ''
    is_amazon='amazon.com' in merchant
    merchant_copy='Browse the brand’s Amazon storefront for current models, availability, specifications, and prices. Compare the exact listing before ordering.' if is_amazon else 'Browse the brand’s official site for current models, availability, specifications, and prices. Compare the exact product before ordering.'
    merchant_label='Browse on Amazon ↗' if is_amazon else 'Explore official site ↗'
    merchant_rel='noopener sponsored nofollow' if is_amazon else 'noopener'
    b=f'''<div class="article-layout container"><article class="story"><div class="crumb"><a href="/">Home</a> / <a href="{caturl(c)}">{e(c)}</a></div><div class="eyebrow"><span class="dot"></span>{e(c)}</div><h1>{e(title)}</h1><p class="dek">{e(scene)}</p><p class="meta">By Catonlee Editors · Updated November 7, 2026 · 5 min read</p><p class="disclosure">Shopping note: This guide uses published product information and practical buying criteria. We have not independently tested the products mentioned. Some outbound links may earn us a commission. <a href="/affiliate-disclosure/">How our links work</a>.</p><figure class="story-cover"><img src="{image(i)}" alt="{e(photo_query(i))}"><figcaption>Image credit and license details are listed on our <a href="/image-credits/">image credits</a> page.</figcaption></figure><div class="prose"><p>{e(scene)} Instead of beginning with a long feature list, begin with what happens in this space on an ordinary day. The most useful purchase is the one that fits the room and reduces a task you already repeat.</p><h2>Start with the real-life job</h2><p>{e(advice)} Before you compare models, note the room's dimensions, where a device could sit, which outlet or charging point it would use, and how often someone will clean, refill, or put it away. These simple constraints can rule out an attractive option before you spend money.</p><p>Think about the moments when the product will be used most. A setup that works on a quiet weekend may be less convenient on a rushed weekday. If more than one person shares the space, easy controls and a predictable place to store accessories can matter as much as advanced features.</p><h2>What to compare before you buy</h2><ul><li><strong>Fit:</strong> Check the product's published dimensions against the space you actually have, including clearance for doors, vents, or cords.</li><li><strong>Daily upkeep:</strong> Look at filters, tanks, brushes, pads, cables, or other parts you will need to maintain.</li><li><strong>Compatibility:</strong> Confirm power, outlets, surfaces, accessories, and device support on the current product page.</li><li><strong>Cost over time:</strong> Include replacement parts and any consumables in your decision, not just the initial price.</li></ul>{detail_html}<h2>The tradeoff to keep in mind</h2><p>{e(tradeoff)} This is where a simpler model may be the better choice. A product that wins on a specification sheet can still disappoint if it is hard to carry, clean, charge, or store in your home.</p><div class="shop-box"><div><span class="eyebrow">Explore the category</span><h3>See current options from {e(brand)}</h3><p>{e(merchant_copy)}</p></div><a class="button" href="{e(merchant)}" target="_blank" rel="{merchant_rel}">{merchant_label}</a></div><h2>Our practical take</h2><p>Choose the option that solves your most frequent problem while fitting the space and maintenance routine you already have. If two models seem equally capable, favor the one with clearer documentation, accessible replacement parts, and a straightforward return policy. Check the latest seller listing because features, availability, and prices can change.</p><h2>Questions worth asking</h2><h3>Do I need the most expensive model?</h3><p>Usually not. Pay for a feature when you can explain how it will improve a task you repeat. Skip upgrades that do not match your room or routine.</p><h3>What should I verify on the product page?</h3><p>Confirm dimensions, compatibility, included accessories, power requirements, warranty terms, and the current seller and return information.</p></div></article><aside class="sidebar"><div class="side-label"><span class="dot"></span>More to explore</div>{''.join('<a href="'+url(x)+'"><img src="'+image(j)+'" alt=""><span>'+e(x[1])+'</span></a>' for j,x in related)}</aside></div><section class="container related"><div class="section-head"><h2>Keep reading</h2><a href="{caturl(c)}">More in {e(c)} ↗</a></div><div class="grid grid-3">{''.join(card(x,j) for j,x in related)}</div></section>'''
    schema=json.dumps({'@context':'https://schema.org','@type':'Article','headline':title,'description':scene,'dateModified':'2026-11-07','author':{'@type':'Organization','name':'Catonlee Editors'},'publisher':{'@type':'Organization','name':'Catonlee'},'mainEntityOfPage':'https://catonlee.com'+url(a)})
    write(url(a),shell(title,scene,b,url(a),'<script type="application/ld+json">'+schema+'</script>'))

pages={
'about':('About Catonlee','Catonlee is an independent English-language home and everyday technology publication. We help readers choose useful appliances and devices by starting with real rooms, habits, and budgets. Our guides are based on published specifications and buying criteria; we do not claim hands-on testing unless an article explicitly says so. We explain tradeoffs, link to current product pages, and update guidance when it becomes outdated.'),
'contact':('Contact','Have a question, correction, or product suggestion? Email our editorial team at <a href="mailto:hello@catonlee.com">hello@catonlee.com</a>. For rights or privacy questions, use the same address and include the page URL. We read messages but cannot guarantee an individual response.'),
'privacy-policy':('Privacy Policy','Catonlee is a static publication. Our hosting provider may process technical data such as IP address and browser information to deliver the site and protect it from abuse. We do not operate user accounts or collect payment information. If you email us, we use your message only to respond and manage the correspondence. External merchants and image sources may have their own privacy practices. Contact <a href="mailto:hello@catonlee.com">hello@catonlee.com</a> with privacy questions.'),
'terms':('Terms of Use','Catonlee provides general editorial information, not professional advice. Product details, availability, and prices may change; check the merchant listing before purchasing. We aim for accuracy but cannot guarantee that every statement remains current. Content and original site design belong to Catonlee, while credited images retain their respective licenses. You may link to our pages, but do not republish our articles without permission. Contact us about errors or rights concerns.'),
'affiliate-disclosure':('Affiliate Disclosure','Catonlee may earn a commission when readers purchase through qualifying merchant links, at no extra cost to them. Our current brand-store and official-brand links do not contain affiliate tracking until an approved program account and tracking details are configured. Commercial relationships do not change our editorial criteria. We do not claim hands-on testing when we have only reviewed published information. Product availability and price are controlled by the merchant.'),
'cookie-notice':('Cookie Notice','Catonlee does not currently set optional analytics or advertising cookies on this site. Essential hosting and security systems may use technical storage to deliver pages and prevent abuse. When you follow a link to an external merchant, that service may set its own cookies under its policy. If our cookie practices change, we will update this notice and provide choices where required.'),
}
for key,(title,copy) in pages.items():
    b=f'<section class="legal container"><div class="eyebrow"><span class="dot"></span>Catonlee</div><h1>{title}</h1><p>{copy}</p><p class="date">Last updated November 7, 2026.</p></section>'
    write('/'+key+'/',shell(title,title+' at Catonlee.',b,'/'+key+'/'))
credit_rows=''.join(f'<li><a href="{e(x.get("source","#"))}" target="_blank" rel="noopener">Article {x["index"]:02d}: {e(x["query"])}</a> — {e(x.get("author","Unknown creator"))}; {e(x.get("license","license pending"))}</li>' for x in credits if x.get('file'))
write('/image-credits/',shell('Image Credits','Licenses and sources for Catonlee editorial images.','<section class="legal container"><h1>Image Credits</h1><p>Editorial photographs are sourced from Pexels under the Pexels License. Follow each source link for the photo and current license details.</p><ul>'+credit_rows+'</ul></section>','/image-credits/'))
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://catonlee.com/sitemap.xml\n')
paths=['/','/all-stories/']+[caturl(c) for c in categories]+[url(a) for a in ARTICLES]+['/'+k+'/' for k in pages]+['/image-credits/']
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>https://catonlee.com'+p+'</loc></url>' for p in paths)+'</urlset>')
print('Built',len(paths),'routes; images',len(list((OUT/'images').glob('*'))))
